// Governor decision module — decides whether full probe deliberation should run.

import type { ConsortiumConfig, ExtractedContext, GovernorMode } from "./types.js";

export interface GovernorDecision {
  /** True if full probe deliberation & synthesis should be executed. */
  shouldDeliberate: boolean;
  /** Human-readable reason explaining the decision. */
  reason: string;
}

/** Evaluate whether deliberation should run based on configuration, context, and turn state. */
export function hasExplicitDurableStateSupersession(currentUserTurn: string): boolean {
  const hasReplacementVerb = /\b(?:replace|replaces|replaced|replacing|supersede|supersedes|superseded|superseding|retire|retires|retired|retiring|migrate|migrates|migrated|migrating)\b/i.test(currentUserTurn);
  const hasDurableArtifact = /\bPROJECT_STATE\.md\b|\b[\w.-]+\.ya?ml\b/i.test(currentUserTurn);
  return hasReplacementVerb && hasDurableArtifact;
}

export function shouldDeliberate(
  config: ConsortiumConfig,
  extractedContext?: ExtractedContext,
  turnsSinceLastAudit: number = 0,
  currentUserTurn: string = "",
): GovernorDecision {
  const mode: GovernorMode = config.governorMode ?? "smart_extractor";
  const maxTurnGap = config.maxTurnGap ?? 20;
  const periodicInterval = config.periodicInterval ?? 10;

  if (mode === "always") {
    return {
      shouldDeliberate: true,
      reason: "Mode is 'always' — full audit enabled on every turn",
    };
  }

  if (mode === "manual") {
    return {
      shouldDeliberate: false,
      reason: "Mode is 'manual' — skipped until explicitly triggered",
    };
  }

  if (mode === "periodic") {
    if (turnsSinceLastAudit >= periodicInterval) {
      return {
        shouldDeliberate: true,
        reason: `Periodic turn interval (${periodicInterval}) reached`,
      };
    }
    return {
      shouldDeliberate: false,
      reason: `Periodic turn interval (${periodicInterval}) not reached (${turnsSinceLastAudit}/${periodicInterval})`,
    };
  }

  // mode === "smart_extractor" (default)
  if (turnsSinceLastAudit >= maxTurnGap) {
    return {
      shouldDeliberate: true,
      reason: `Maximum turn gap (${maxTurnGap}) reached — forcing periodic safety audit`,
    };
  }

  if (config.stateSupersessionGuard === true && hasExplicitDurableStateSupersession(currentUserTurn)) {
    return {
      shouldDeliberate: true,
      reason: "Explicit durable-state supersession guard",
    };
  }

  if (extractedContext) {
    if (extractedContext.deliberationNeeded === false) {
      return {
        shouldDeliberate: false,
        reason: extractedContext.deliberationReason || "Context extraction determined full probe audit is not needed",
      };
    }
    if (extractedContext.deliberationNeeded === true) {
      return {
        shouldDeliberate: true,
        reason: extractedContext.deliberationReason || "Context extraction identified active gaps or unverified changes",
      };
    }
  }

  // Fallback default if extraction data is unavailable
  return {
    shouldDeliberate: true,
    reason: "No extraction signal available — defaulting to full audit for safety",
  };
}

// ConsortiumCore — pure logic, no Pi dependency.
// Orchestrates divergence (parallel probes) and convergence (synthesis).

import type { ConsortiumConfig, DeliberationResult, ProbeResult, ProgressCallback, ExtractedContext } from "./types.js";
import type { AgentMessage } from "@earendil-works/pi-agent-core";
import { extractContextFromMessages, getDefaultExtractedContext } from "./extraction.js";
import { buildProbeInputXml, formatAgentMessageContent } from "./context.js";
import { shouldDeliberate } from "./governor.js";

/** Injectable model call function (mockable for tests). */
export type ModelCallFn = (
  modelKey: string,
  system: string,
  user: string,
  maxTokens: number,
  temperature: number,
  signal: AbortSignal | undefined,
) => Promise<string>;

/** Validate probe output — must start with NO_CONTRIBUTION or severity tag.
 * If the model ignored instructions and answered the user's question,
 * coerce to NO_CONTRIBUTION so it never reaches synthesis.
 *
 * Normalizes a leading "TAG " prefix (e.g. "TAG INFO x" → "INFO x")
 * before validation, recovering outputs where the model wrote the
 * placeholder literally. */
function validateProbeOutput(text: string): string {
  let trimmed = text.trim();
  // Strip leading "TAG " if followed by a recognized severity tag.
  if (trimmed.startsWith("TAG ") && /^(INFO|WARN|BLOCK)\s+\S/.test(trimmed.slice(4))) {
    trimmed = trimmed.slice(4);
  }
  // Also handle "TAG NO_CONTRIBUTION".
  if (trimmed === "TAG NO_CONTRIBUTION") {
    trimmed = "NO_CONTRIBUTION";
  }
  if (trimmed.startsWith("NO_CONTRIBUTION")) return trimmed;
  // Match severity tag followed by any non-whitespace (not just space).
  // Bare tags like "WARN\n" with no content are invalid.
  if (/^(INFO|WARN|BLOCK)\s+\S/.test(trimmed)) return trimmed;
  // Model ignored instructions or emitted bare tag — discard output
  return "NO_CONTRIBUTION";
}

const CONSORTIUM_SYNTHETIC_PREFIX = "[CONSORTIUM DELIBERATION]";

/** Return the latest human-authored user turn, normalized across Pi message content shapes. */
export function getCurrentHumanUserTurn(messages: AgentMessage[]): string {
  for (let index = messages.length - 1; index >= 0; index--) {
    const message = messages[index];
    if (message.role !== "user") continue;
    const content = formatAgentMessageContent(message);
    if (content.startsWith(CONSORTIUM_SYNTHETIC_PREFIX)) continue;
    return content;
  }
  return "";
}

export class ConsortiumCore {
  private lastExtractedContext?: ExtractedContext;

  constructor(
    private config: ConsortiumConfig,
    private callModel: ModelCallFn,
    private onBaselineCheck?: (baselineSupplied: boolean) => void,
  ) {}

  async deliberate(
    input: string | AgentMessage[],
    externalSignal?: AbortSignal,
    onProgress?: ProgressCallback,
    turnsSinceLastAudit: number = 0,
    previousContext?: ExtractedContext,
  ): Promise<DeliberationResult> {
    if (externalSignal?.aborted) {
      throw new Error("Deliberation aborted");
    }

    const masterController = new AbortController();
    if (externalSignal) {
      if (externalSignal.aborted) {
        masterController.abort();
      } else {
        externalSignal.addEventListener("abort", () => masterController.abort(), { once: true });
      }
    }

    const errors: string[] = [];
    const probeTotal = this.config.probes.length;

    // Phase 0.5 (Pre-check): Evaluate governor gate before extraction if context is not required (e.g. periodic or manual mode)
    const preGovernorDecision = shouldDeliberate(this.config, undefined, turnsSinceLastAudit);
    if (!preGovernorDecision.shouldDeliberate) {
      onProgress?.("complete", 0, 0);
      return {
        probes: [],
        synthesis: "NO_CONTRIBUTION",
        extractedContext: undefined,
        skippedByGovernor: true,
        governorReason: preGovernorDecision.reason,
        errors: errors.length > 0 ? errors : undefined,
      };
    }

    let userContext: string;
    let extractedContext: ExtractedContext | undefined;

    if (Array.isArray(input)) {
      // Phase 0: Extraction pass
      onProgress?.("extraction", 0, 1);
      try {
        const priorContext = previousContext ?? this.lastExtractedContext;
        const baselineSupplied = priorContext !== undefined;
        try { this.onBaselineCheck?.(baselineSupplied); } catch { /* isolated */ }
        extractedContext = await extractContextFromMessages(input, this.callModel, priorContext, masterController.signal);
        this.lastExtractedContext = extractedContext;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        errors.push(`Extraction: ${msg}`);
        extractedContext = getDefaultExtractedContext(input);
      }
      userContext = buildProbeInputXml(input, extractedContext);
    } else {
      userContext = input;
    }

    const currentUserTurn = Array.isArray(input)
      ? getCurrentHumanUserTurn(input)
      : "";

    // Phase 0.5 (Post-extraction): Re-evaluate governor gate with extracted context (e.g. for smart_extractor mode)
    const governorDecision = shouldDeliberate(this.config, extractedContext, turnsSinceLastAudit, currentUserTurn);
    if (!governorDecision.shouldDeliberate) {
      onProgress?.("complete", 0, 0);
      return {
        probes: [],
        synthesis: "NO_CONTRIBUTION",
        extractedContext,
        skippedByGovernor: true,
        governorReason: governorDecision.reason,
        errors: errors.length > 0 ? errors : undefined,
      };
    }

    // Phase 1: Divergence — parallel or serial probes
    const probeResults = await this.runProbes(userContext, masterController.signal, errors, onProgress, probeTotal);

    // Skip synthesis if all probes had nothing to contribute
    const allNoContribution = probeResults.every(
      (p) => p.text.trim().startsWith("NO_CONTRIBUTION"),
    );
    if (allNoContribution) {
      onProgress?.("complete", 0, 0);
      return {
        probes: probeResults,
        synthesis: "NO_CONTRIBUTION",
        extractedContext,
        governorReason: governorDecision.reason,
        errors: errors.length > 0 ? errors : undefined,
      };
    }

    // Phase 2: Convergence — synthesis
    onProgress?.("synthesis", 0, 1);
    const synthesisUser = this.formatProbeInputs(probeResults);
    const synthesis = await this.runSynthesis(synthesisUser, masterController.signal, errors);

    onProgress?.("complete", 0, 0);
    return {
      probes: probeResults,
      synthesis,
      extractedContext,
      governorReason: governorDecision.reason,
      errors: errors.length > 0 ? errors : undefined,
    };
  }

  private async runProbes(
    userContext: string,
    signal: AbortSignal,
    errors: string[],
    onProgress?: ProgressCallback,
    probeTotal?: number,
  ): Promise<ProbeResult[]> {
    const mode = this.config.executionMode ?? "serial";

    if (mode === "serial") {
      return this.runProbesSerial(userContext, signal, errors, onProgress, probeTotal);
    }

    return this.runProbesParallel(userContext, signal, errors, onProgress, probeTotal);
  }

  private async runProbesParallel(
    userContext: string,
    signal: AbortSignal,
    errors: string[],
    onProgress?: ProgressCallback,
    probeTotal?: number,
  ): Promise<ProbeResult[]> {
    let completed = 0;

    const probePromises = this.config.probes.map(async (probe, i) => {
      const probeController = new AbortController();
      const onMasterAbort = () => probeController.abort();
      signal.addEventListener("abort", onMasterAbort, { once: true });

      const timeoutId = setTimeout(() => probeController.abort(), this.config.probeTimeoutMs);

      try {
        const probeUser = probe.roleLens
          ? `${userContext}\n\n---\n\n${probe.roleLens}`
          : userContext;
        const result = await this.callModel(
          `probe:${i}:${probe.role}`,
          probe.systemPrompt,
          probeUser,
          this.config.maxProbeTokens,
          this.config.probeTemperature,
          probeController.signal,
        );
        const validated = validateProbeOutput(result);
        return { role: probe.role, text: validated };
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        errors.push(`Probe "${probe.role}": ${msg}`);
        return { role: probe.role, text: `[error: ${msg}]` };
      } finally {
        clearTimeout(timeoutId);
        signal.removeEventListener("abort", onMasterAbort);
        completed++;
        onProgress?.("probe", completed, probeTotal ?? this.config.probes.length, probe.role);
      }
    });

    return Promise.all(probePromises);
  }

  private async runProbesSerial(
    userContext: string,
    signal: AbortSignal,
    errors: string[],
    onProgress?: ProgressCallback,
    probeTotal?: number,
  ): Promise<ProbeResult[]> {
    const results: ProbeResult[] = [];
    const total = probeTotal ?? this.config.probes.length;
    for (const [i, probe] of this.config.probes.entries()) {
      const probeController = new AbortController();
      const onMasterAbort = () => probeController.abort();
      signal.addEventListener("abort", onMasterAbort, { once: true });

      const timeoutId = setTimeout(() => probeController.abort(), this.config.probeTimeoutMs);

      try {
        const probeUser = probe.roleLens
          ? `${userContext}\n\n---\n\n${probe.roleLens}`
          : userContext;
        const result = await this.callModel(
          `probe:${i}:${probe.role}`,
          probe.systemPrompt,
          probeUser,
          this.config.maxProbeTokens,
          this.config.probeTemperature,
          probeController.signal,
        );
        const validated = validateProbeOutput(result);
        results.push({ role: probe.role, text: validated });
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        errors.push(`Probe "${probe.role}": ${msg}`);
        results.push({ role: probe.role, text: `[error: ${msg}]` });
      } finally {
        clearTimeout(timeoutId);
        signal.removeEventListener("abort", onMasterAbort);
        onProgress?.("probe", i + 1, total, probe.role);
      }
    }
    return results;
  }

  private async runSynthesis(
    synthesisUser: string,
    signal: AbortSignal,
    errors: string[],
  ): Promise<string> {
    try {
      return await this.callModel(
        "synthesis",
        this.config.synthesis.systemPrompt,
        synthesisUser,
        this.config.maxSynthesisTokens,
        this.config.synthesisTemperature,
        signal,
      );
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push(`Synthesis: ${msg}`);
      return `[Synthesis failed: ${msg}]. Raw probes follow.`;
    }
  }

  private formatProbeInputs(probes: ProbeResult[]): string {
    return probes
      .map((p) => `## ${p.role.toUpperCase()} PROBE\n${p.text}`)
      .join("\n\n---\n\n");
  }

}

import { describe, it, expect } from "vitest";
import { shouldDeliberate } from "../src/governor.js";
import type { ConsortiumConfig, ExtractedContext } from "../src/types.js";
import { DEFAULT_CONFIG } from "../src/config.js";

const baseExtractedContext: ExtractedContext = {
  userIntentAndMotive: "Test task",
  activeConstraintsAndGuards: "Standard",
  verifiedFactsInventory: "None",
  evidenceFreshnessDelta: "Fresh",
  clarityAndAmbiguityScore: "CLEAR",
  deliberationNeeded: true,
  deliberationReason: "Unverified code change detected",
};

describe("Governor Decision Engine", () => {
  it("always mode returns true regardless of turn count or context", () => {
    const config: ConsortiumConfig = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "always",
    };

    const res = shouldDeliberate(config, baseExtractedContext, 5);
    expect(res.shouldDeliberate).toBe(true);
    expect(res.reason).toContain("always");
  });

  it("manual mode returns false unless manually triggered", () => {
    const config: ConsortiumConfig = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "manual",
    };

    const res = shouldDeliberate(config, baseExtractedContext, 5);
    expect(res.shouldDeliberate).toBe(false);
    expect(res.reason).toContain("manual");
  });

  it("periodic mode triggers on every N turns", () => {
    const config: ConsortiumConfig = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "periodic",
      periodicInterval: 3,
    };

    expect(shouldDeliberate(config, baseExtractedContext, 0).shouldDeliberate).toBe(false);
    expect(shouldDeliberate(config, baseExtractedContext, 1).shouldDeliberate).toBe(false);
    expect(shouldDeliberate(config, baseExtractedContext, 2).shouldDeliberate).toBe(false);
    expect(shouldDeliberate(config, baseExtractedContext, 3).shouldDeliberate).toBe(true);
  });

  it("smart_extractor mode respects deliberationNeeded boolean from context", () => {
    const config: ConsortiumConfig = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "smart_extractor",
      maxTurnGap: 20,
    };

    const skipContext: ExtractedContext = {
      ...baseExtractedContext,
      deliberationNeeded: false,
      deliberationReason: "Routine conversational query",
    };

    const skipRes = shouldDeliberate(config, skipContext, 5);
    expect(skipRes.shouldDeliberate).toBe(false);
    expect(skipRes.reason).toBe("Routine conversational query");

    const auditRes = shouldDeliberate(config, baseExtractedContext, 5);
    expect(auditRes.shouldDeliberate).toBe(true);
    expect(auditRes.reason).toBe("Unverified code change detected");
  });

  it("forces deliberation only for an enabled explicit durable-state supersession", () => {
    const skipContext: ExtractedContext = {
      ...baseExtractedContext,
      deliberationNeeded: false,
      deliberationReason: "Routine conversational query",
    };
    const config = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "smart_extractor" as const,
      stateSupersessionGuard: true,
    };

    const supersession = shouldDeliberate(
      config,
      skipContext,
      0,
      "Decision: replace PROJECT_STATE.md YAML with Markdown; retain the prior requirement as historical.",
    );
    expect(supersession).toEqual({
      shouldDeliberate: true,
      reason: "Explicit durable-state supersession guard",
    });

    expect(shouldDeliberate(config, skipContext, 0, "Format PROJECT_STATE.md for readability.").shouldDeliberate).toBe(false);
    expect(shouldDeliberate({ ...config, stateSupersessionGuard: false }, skipContext, 0, "Replace PROJECT_STATE.md YAML with Markdown.").shouldDeliberate).toBe(false);
  });

  it("smart_extractor mode forces audit when maxTurnGap is reached", () => {
    const config: ConsortiumConfig = {
      ...DEFAULT_CONFIG,
      probes: [],
      synthesis: { systemPrompt: "", provider: "openai", modelId: "gpt-4o" },
      governorMode: "smart_extractor",
      maxTurnGap: 20,
    };

    const skipContext: ExtractedContext = {
      ...baseExtractedContext,
      deliberationNeeded: false,
      deliberationReason: "Routine conversational query",
    };

    // On 20th turn gap, force audit even if deliberationNeeded is false
    const res = shouldDeliberate(config, skipContext, 20);
    expect(res.shouldDeliberate).toBe(true);
    expect(res.reason).toContain("Maximum turn gap (20) reached");
  });
});

